import { RadioGroup } from "vaiperui";

<RadioGroup
  label="Plan"
  defaultValue="free"
  onValueChange={(plan) => console.log(plan)}
  options={[
    { value: "free", label: "Free", description: "Para proyectos personales" },
    { value: "pro", label: "Pro", description: "Para equipos pequeños" },
    { value: "team", label: "Team", disabled: true },
  ]}
/>

import { Slider } from "vaiperui";

const [volume, setVolume] = useState([40]);
const [price, setPrice] = useState([200, 800]);

<p>Volumen: {volume[0]}%</p>
<Slider aria-label="Volumen" value={volume} onValueChange={setVolume} />

<Slider
  aria-label="Precio"
  thumbLabels={["Precio mínimo", "Precio máximo"]}
  value={price}
  onValueChange={setPrice}
  min={0}
  max={1000}
  step={10}
/>

import { Upload } from "vaiperui";

const [files, setFiles] = useState<File[]>([]);

<Upload
  multiple
  accept=".pdf,image/*"
  label="Adjuntos"
  description="PDF o imagen, hasta 5 MB"
  onFilesChange={(chosen) => setFiles((current) => [...current, ...chosen])}
/>

import { Calendar } from "vaiperui";

const [date, setDate] = useState<Date>();
const [period, setPeriod] = useState<DateRange>({});

<Calendar value={date} onValueChange={setDate} />
<Calendar mode="range" value={period} onValueChange={setPeriod} />

import { DatePicker } from "vaiperui";

const [date, setDate] = useState<Date>();

<DatePicker label="Fecha de entrega" value={date} onValueChange={setDate} />
<DatePicker
  label="Fecha de entrega"
  minDate={new Date()}
  weekStartsOn={1}
  locale="es-ES"
/>

import { DateRangePicker, getDatePresets, type DateRange } from "vaiperui";

const [period, setPeriod] = useState<DateRange>({});

<DateRangePicker label="Estancia" presets value={period} onValueChange={setPeriod} />

// Custom list, translated labels
<DateRangePicker presets={[
  ...getDatePresets({ today: "Hoy" }).slice(0, 3),
  { label: "Q4", range: { from: new Date(2026, 9, 1), to: new Date(2026, 11, 31) } },
]} />

import { TimePicker } from "vaiperui";

const [time, setTime] = useState("14:30");

<TimePicker label="Hora" value={time} onValueChange={setTime} />
<TimePicker label="Hora" hour12 minuteStep={15} />

import { DateTimePicker } from "vaiperui";

const [when, setWhen] = useState<Date>();

<DateTimePicker label="Cita" value={when} onValueChange={setWhen} />
<DateTimePicker label="Cita" hour12 minuteStep={15} minDate={new Date()} />

import { Badge } from "vaiperui";

<Badge status="success" dot>Activo</Badge>
<Badge status="warning">Atención</Badge>

import { List, ListItem, Avatar, Badge } from "vaiperui";

<List divided>
  <ListItem
    leading={<Avatar name="Camila Souza" />}
    title="Camila Souza"
    description="Diseñadora de producto"
    trailing={<Badge status="success">Activa</Badge>}
  />
</List>

import { Banner, Button } from "vaiperui";

<Banner
  action={<Button size="sm" variant="transparent">Saber más</Button>}
  onDismiss={() => setOpen(false)}
>
